}

/** Abre el selector de archivos .eml. */
function pickEmails() {
  const input = document.createElement("input");
  input.type = "file";
  input.accept = ".eml,message/rfc822";
  input.multiple = true;
  input.addEventListener("change", () => {
    if (input.files && input.files.length) importEmails(input.files);
  });
  input.click();
}

